effects.shader:
vec4 effect(vec2 uv) {
  vec2 p = (uv - 0.5) * vec2(uResolution.x / max(uResolution.y, 1.0), 1.0);
  vec3 light = vec3(0.0);
  float alpha = 0.0;
  for (int i = 0; i < 5; i++) {
    float f = float(i);
    float center = sin(p.x * (2.0 + f * 0.3) + uTime * 0.25 + f) * 0.14 + f * 0.055;
    float ribbon = exp(-abs(p.y - center) * (45.0 - uBands.x * 12.0));
    vec3 color = mix(vec3(0.12, 0.9, 0.65), vec3(0.55, 0.2, 1.0), f / 4.0);
    light += color * ribbon * 0.25;
    alpha += ribbon * 0.18;
  }
  return vec4(light / max(alpha, 0.001), min(alpha, 0.8));
}
